```python
# ======== 自己实现 @property ========
# property 本质上是一个描述符类

class Property:
    '''自己实现的简化版 @property'''
    def __init__(self, fget=None, fset=None, fdel=None):
        self.fget = fget
        self.fset = fset
        self.fdel = fdel

    def __get__(self, instance, owner):
        if instance is None:
            return self  # 类上访问属性时返回描述符本身
        return self.fget(instance)

    def __set__(self, instance, value):
        if self.fset is None:
            raise AttributeError('cannot set attribute')
        self.fset(instance, value)

    def setter(self, fset):
        return type(self)(self.fget, fset, self.fdel)

# 使用自己的 Property
class Circle:
    def __init__(self, radius):
        self._radius = radius

    @Property                           # ① area = Property(area)
    def area(self):
        return 3.14159 * self._radius ** 2

    @Property                           # ② radius = Property(radius)  — 用我们自己的 Property
    def radius(self):
        return self._radius

    @radius.setter                      # ③ radius = Property(radius).setter(radius_setter)
    def radius(self, value):
        if value < 0:
            raise ValueError('半径不能为负')
        self._radius = value

# ======== 装饰器在框架中的典型应用 ========
# Flask 风格的简单路由（演示原理）
class FlaskLike:
    def __init__(self):
        self._routes = {}

    def route(self, path):
        def decorator(func):
            self._routes[path] = func
            return func  # 注意这里返回原函数，只是注册不包装
        return decorator

app = FlaskLike()

@app.route('/hello')
def hello():
    return 'Hello World'

# app._routes 现在是 {'/hello': <function hello>}
# 当请求来到 /hello 时调用 app._routes['/hello']()

# ======== 装饰器用于权限校验 ========
def require_auth(user_role):
    def decorator(func):
        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            # 假设从某个地方获取当前用户角色
            current_user = get_current_user_role()
            if current_user != user_role:
                raise PermissionError(f'需要 {user_role} 权限')
            return func(*args, **kwargs)
        return wrapper
    return decorator

@require_auth('admin')
def delete_user(user_id):
    print(f'删除用户 {user_id}')
```

