        pass

    def __get__(self, instance, owner):
        # 在这里编写你的代码
        pass

    def __set__(self, instance, value):
        # 在这里编写你的代码
        pass

    def setter(self, func):
        # 在这里编写你的代码
        pass


# ====== 测试代码 ======
class Temperature:
    def __init__(self, celsius=0):
        self._celsius = celsius

    @custom_property
    def celsius(self):
        return self._celsius

    @celsius.setter
    def celsius(self, value):
        if value < -273.15:
            raise ValueError('温度不能低于绝对零度')
        self._celsius = value

    @custom_property
    def fahrenheit(self):
        return self._celsius * 9/5 + 32


t = Temperature(25)
print(t.celsius)       # 25
t.celsius = 30
print(t.fahrenheit)    # 86.0
try:
    t.fahrenheit = 100  # 应该抛出 AttributeError (只读)
except AttributeError:
    print('只读属性不可设置')
try:
    t.celsius = -300    # 应该抛出 ValueError
except ValueError:
    print('检测到非法温度')
```
